import { Controller, HttpCode, Post, Put, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const QUESTION_TYPES = ['선택형', '주관식'];
const SELECTION_MODES = ['단답', '다답'];

interface Db {
  query(sql: string, params?: Record<string, unknown>): Promise<Record<string, unknown>[]>;
  execute(sql: string, params?: Record<string, unknown>): Promise<number>;
}

interface OptionInput {
  optionText: string;
  sortOrder: number;
}

interface QuestionInput {
  title: string;
  questionType: string;
  selectionMode: string | null;
  otherOpinionAllowed: boolean;
  sortOrder: number | null;
  options: OptionInput[] | null;
}

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function isBlank(v: unknown): boolean {
  return typeof v !== 'string' || v.trim() === '';
}

function requiredId(v: unknown, label: string): number {
  if (typeof v !== 'number' || !Number.isInteger(v) || v <= 0) {
    throw invalid(label + '을(를) 올바르게 입력해 주세요.');
  }
  return v;
}

function optionalOrder(v: unknown, label: string): number | null {
  if (v === undefined || v === null || v === '') {
    return null;
  }
  if (typeof v !== 'number' || !Number.isInteger(v) || v < 0) {
    throw invalid(label + '은(는) 0 이상의 정수여야 합니다.');
  }
  return v;
}

// 보기 목록: [{optionText, sortOrder}] 또는 문자열 배열 (가정: 필드 이름은 optionText·sortOrder)
function parseOptions(v: unknown): OptionInput[] | null {
  if (v === undefined || v === null) {
    return null;
  }
  if (!Array.isArray(v)) {
    throw invalid('보기 목록 형식이 올바르지 않습니다.');
  }
  const list: OptionInput[] = v.map((item: unknown, index: number) => {
    let text: unknown = item;
    let order: number | null = null;
    if (item !== null && typeof item === 'object') {
      const o = item as Record<string, unknown>;
      text = o['optionText'];
      order = optionalOrder(o['sortOrder'], '보기 순서');
    }
    if (isBlank(text)) {
      throw new ApiError(422, 'INVALID_QUESTION_OPTIONS', '보기 내용을 입력해 주세요.');
    }
    return { optionText: String(text).trim(), sortOrder: order === null ? index : order };
  });
  return list.sort((a, b) => a.sortOrder - b.sortOrder);
}

function parseQuestion(data: Record<string, unknown>): QuestionInput {
  if (isBlank(data['title'])) {
    throw new ApiError(422, 'SURVEY_QUESTION_TITLE_REQUIRED', '설문항목 제목을 입력해 주세요.');
  }
  const title = String(data['title']).trim();
  if (title.length > 500) {
    throw invalid('설문항목 제목은 500자 이하로 입력해 주세요.');
  }
  const questionType = data['questionType'];
  if (typeof questionType !== 'string' || !QUESTION_TYPES.includes(questionType)) {
    throw invalid('문항 유형은 선택형 또는 주관식이어야 합니다.');
  }
  if (typeof data['otherOpinionAllowed'] !== 'boolean') {
    throw invalid('기타의견 허용 여부를 입력해 주세요.');
  }
  const sortOrder = optionalOrder(data['sortOrder'], '표시 순서');
  const options = parseOptions(data['options']);
  let selectionMode: string | null = null;
  if (questionType === '선택형') {
    const mode = data['selectionMode'];
    if (typeof mode !== 'string' || !SELECTION_MODES.includes(mode)) {
      throw new ApiError(422, 'INVALID_QUESTION_OPTIONS', '선택형 문항은 단답 또는 다답을 지정해야 합니다.');
    }
    selectionMode = mode;
  }
  return {
    title,
    questionType,
    selectionMode,
    otherOpinionAllowed: data['otherOpinionAllowed'],
    sortOrder,
    options: questionType === '선택형' ? options : null,
  };
}

async function insertOptions(db: Db, questionId: number, options: OptionInput[]): Promise<void> {
  for (const opt of options) {
    await db.execute(
      `INSERT INTO survey_option (survey_question_id, option_text, sort_order, created_at, updated_at)
       VALUES (CAST(:questionId AS bigint), :optionText, CAST(:sortOrder AS integer), now(), now())`,
      { questionId, optionText: opt.optionText, sortOrder: opt.sortOrder },
    );
  }
}

@Controller('api/v1')
export class FnSfr03502Controller {
  @Post('/survey-questions')
  @HttpCode(200)
  async createSurveyQuestion(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const surveyId = requiredId(data['surveyId'], '설문조사');
    const input = parseQuestion(data);
    if (input.questionType === '선택형' && (input.options === null || input.options.length === 0)) {
      throw new ApiError(422, 'INVALID_QUESTION_OPTIONS', '선택형 문항은 보기를 하나 이상 등록해야 합니다.');
    }
    return transaction(async (db) => {
      const surveys = await db.query(
        'SELECT survey_id FROM survey WHERE survey_id = CAST(:surveyId AS bigint)',
        { surveyId },
      );
      if (surveys.length === 0) {
        throw new ApiError(404, 'SURVEY_NOT_FOUND', '설문조사를 찾을 수 없습니다.');
      }
      const rows = await db.query(
        `INSERT INTO survey_question (survey_id, title, question_type, selection_mode, other_opinion_allowed, sort_order, created_at, updated_at)
         VALUES (CAST(:surveyId AS bigint), :title, :questionType, :selectionMode, :other, CAST(:sortOrder AS integer), now(), now())
         RETURNING survey_question_id AS "surveyQuestionId", title AS "title", question_type AS "questionType",
                   selection_mode AS "selectionMode", other_opinion_allowed AS "otherOpinionAllowed"`,
        {
          surveyId,
          title: input.title,
          questionType: input.questionType,
          selectionMode: input.selectionMode,
          other: input.otherOpinionAllowed,
          sortOrder: input.sortOrder,
        },
      );
      const created = rows[0];
      if (input.options !== null) {
        await insertOptions(db, Number(created['surveyQuestionId']), input.options);
      }
      return created;
    });
  }

  @Put('/survey-questions/:surveyQuestionId')
  async updateSurveyQuestion(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const idText = req.params['surveyQuestionId'];
    const questionId = Number(idText);
    if (!/^[0-9]+$/.test(idText) || !Number.isSafeInteger(questionId)) {
      throw invalid('설문항목 ID가 올바르지 않습니다.');
    }
    const data = checks.inputOf(req.body);
    const input = parseQuestion(data);
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT question_type AS "questionType", selection_mode AS "selectionMode", other_opinion_allowed AS "otherOpinionAllowed"
         FROM survey_question WHERE survey_question_id = CAST(:questionId AS bigint) FOR UPDATE`,
        { questionId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'SURVEY_QUESTION_NOT_FOUND', '설문항목을 찾을 수 없습니다.');
      }
      const current = found[0];
      const counts = await db.query(
        `SELECT COUNT(*) AS "total", COUNT(other_opinion) AS "otherTotal"
         FROM survey_answer WHERE survey_question_id = CAST(:questionId AS bigint)`,
        { questionId },
      );
      const hasAnswers = Number(counts[0]['total']) > 0;
      const hasOtherOpinions = Number(counts[0]['otherTotal']) > 0;
      const existingOptions = await db.query(
        `SELECT option_text AS "optionText" FROM survey_option
         WHERE survey_question_id = CAST(:questionId AS bigint) ORDER BY sort_order, survey_option_id`,
        { questionId },
      );
      if (hasAnswers) {
        // 결정: 이미 응답이 있으면 기존 응답에 영향이 없는 변경만 허용
        const sameType = current['questionType'] === input.questionType;
        const sameMode = (current['selectionMode'] ?? null) === input.selectionMode;
        const sameOptions =
          input.options === null ||
          JSON.stringify(input.options.map((o) => o.optionText)) ===
            JSON.stringify(existingOptions.map((o) => o['optionText']));
        const otherRemoved = current['otherOpinionAllowed'] === true && !input.otherOpinionAllowed && hasOtherOpinions;
        if (!sameType || !sameMode || !sameOptions || otherRemoved) {
          throw new ApiError(409, 'SURVEY_QUESTION_HAS_ANSWERS', '이미 제출된 응답이 있어 문항 구조를 변경할 수 없습니다.');
        }
      }
      if (input.questionType === '선택형') {
        if (input.options !== null && input.options.length === 0) {
          throw new ApiError(422, 'INVALID_QUESTION_OPTIONS', '선택형 문항은 보기를 하나 이상 등록해야 합니다.');
        }
        if (input.options === null && existingOptions.length === 0) {
          throw new ApiError(422, 'INVALID_QUESTION_OPTIONS', '선택형 문항은 보기를 하나 이상 등록해야 합니다.');
        }
      }
      const rows = await db.query(
        `UPDATE survey_question
         SET title = :title, question_type = :questionType, selection_mode = :selectionMode,
             other_opinion_allowed = :other, sort_order = CAST(:sortOrder AS integer), updated_at = now()
         WHERE survey_question_id = CAST(:questionId AS bigint)
         RETURNING survey_question_id AS "surveyQuestionId", title AS "title", question_type AS "questionType",
                   selection_mode AS "selectionMode", other_opinion_allowed AS "otherOpinionAllowed"`,
        {
          questionId,
          title: input.title,
          questionType: input.questionType,
          selectionMode: input.selectionMode,
          other: input.otherOpinionAllowed,
          sortOrder: input.sortOrder,
        },
      );
      if (input.questionType === '주관식') {
        await db.execute('DELETE FROM survey_option WHERE survey_question_id = CAST(:questionId AS bigint)', { questionId });
      } else if (input.options !== null && !hasAnswers) {
        await db.execute('DELETE FROM survey_option WHERE survey_question_id = CAST(:questionId AS bigint)', { questionId });
        await insertOptions(db, questionId, input.options);
      }
      return rows[0];
    });
  }

  @Post('/survey-answers')
  @HttpCode(200)
  async createSurveyAnswer(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const questionId = requiredId(data['surveyQuestionId'], '설문항목');
    const rawOption = data['surveyOptionId'];
    const optionId = rawOption === undefined || rawOption === null || rawOption === '' ? null : requiredId(rawOption, '선택 보기');
    const answerText = isBlank(data['answerText']) ? null : String(data['answerText']);
    const otherOpinion = isBlank(data['otherOpinion']) ? null : String(data['otherOpinion']);
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT q.question_type AS "questionType", q.selection_mode AS "selectionMode",
                q.other_opinion_allowed AS "otherOpinionAllowed",
                (CURRENT_DATE BETWEEN s.start_date AND s.end_date) AS "inPeriod"
         FROM survey_question q JOIN survey s ON s.survey_id = q.survey_id
         WHERE q.survey_question_id = CAST(:questionId AS bigint)`,
        { questionId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'SURVEY_QUESTION_NOT_FOUND', '설문항목을 찾을 수 없습니다.');
      }
      const question = found[0];
      // 가정: 설문 기간 밖이면 응답 입력을 차단한다 (오류 코드가 표에 없어 INVALID_STATE)
      if (question['inPeriod'] !== true) {
        throw new ApiError(409, 'INVALID_STATE', '설문 기간이 아니어서 응답을 입력할 수 없습니다.');
      }
      if (otherOpinion !== null && question['otherOpinionAllowed'] !== true) {
        throw invalid('이 문항은 기타 의견을 입력할 수 없습니다.');
      }
      if (question['questionType'] === '선택형') {
        if (optionId === null) {
          throw invalid('보기를 선택해 주세요.');
        }
        if (answerText !== null) {
          throw invalid('선택형 문항에는 주관식 응답을 입력할 수 없습니다.');
        }
        const options = await db.query(
          `SELECT survey_option_id FROM survey_option
           WHERE survey_option_id = CAST(:optionId AS bigint) AND survey_question_id = CAST(:questionId AS bigint)`,
          { optionId, questionId },
        );
        if (options.length === 0) {
          throw invalid('선택한 보기가 이 문항의 보기가 아닙니다.');
        }
        const previous = await db.query(
          `SELECT survey_option_id AS "surveyOptionId" FROM survey_answer
           WHERE survey_question_id = CAST(:questionId AS bigint) AND respondent_id = CAST(:userId AS bigint)`,
          { questionId, userId: user.id },
        );
        if (question['selectionMode'] === '단답' && previous.length > 0) {
          throw invalid('단답형 문항은 하나의 보기만 선택할 수 있습니다.');
        }
        if (previous.some((p) => Number(p['surveyOptionId']) === optionId)) {
          throw invalid('이미 선택한 보기입니다.');
        }
      } else {
        if (optionId !== null) {
          throw invalid('주관식 문항에는 보기를 선택할 수 없습니다.');
        }
        if (answerText === null) {
          throw invalid('응답 내용을 입력해 주세요.');
        }
      }
      const rows = await db.query(
        `INSERT INTO survey_answer (survey_question_id, survey_option_id, respondent_id, answer_text, other_opinion, created_at, updated_at)
         VALUES (CAST(:questionId AS bigint), CAST(:optionId AS bigint), CAST(:userId AS bigint), :answerText, :otherOpinion, now(), now())
         RETURNING survey_answer_id AS "surveyAnswerId"`,
        { questionId, optionId, userId: user.id, answerText, otherOpinion },
      );
      return rows[0];
    });
  }
}

