import { useState } from 'react';
import { Badge, Band, DataTable, Drawer, Field, Form, LookupSelect, NumberInput, RefName, Select, TextInput, Tiles, call } from '../kit';
import type { PageProps, Row } from '../kit';

type Mode = '' | 'create' | 'edit' | 'answer';

export default function FnSfr03502Page({ role, notify }: PageProps) {
  const [questions, setQuestions] = useState<Row[]>([]);
  const [answers, setAnswers] = useState<Row[]>([]);
  const [mode, setMode] = useState<Mode>('');
  const [editing, setEditing] = useState<Row | null>(null);
  const [surveyId, setSurveyId] = useState<number | string>('');
  const [title, setTitle] = useState('');
  const [questionType, setQuestionType] = useState('선택형');
  const [selectionMode, setSelectionMode] = useState('단답');
  const [otherAllowed, setOtherAllowed] = useState('false');
  const [sortOrder, setSortOrder] = useState<number | string>('');
  const [optionTexts, setOptionTexts] = useState<string[]>(['']);
  const [answerQuestionId, setAnswerQuestionId] = useState<number | string>('');
  const [answerOptionId, setAnswerOptionId] = useState<number | string>('');
  const [answerText, setAnswerText] = useState('');
  const [otherOpinion, setOtherOpinion] = useState('');

  const close = () => {
    setMode('');
    setEditing(null);
  };

  const openCreate = () => {
    setSurveyId('');
    setTitle('');
    setQuestionType('선택형');
    setSelectionMode('단답');
    setOtherAllowed('false');
    setSortOrder('');
    setOptionTexts(['']);
    setEditing(null);
    setMode('create');
  };

  const openEdit = (row: Row) => {
    setEditing(row);
    setSurveyId(row['surveyId'] as number);
    setTitle(String(row['title'] ?? ''));
    setQuestionType(String(row['questionType'] ?? '선택형'));
    setSelectionMode(String(row['selectionMode'] ?? '단답'));
    setOtherAllowed(row['otherOpinionAllowed'] === true ? 'true' : 'false');
    setSortOrder((row['sortOrder'] as number | string) ?? '');
    const saved = (row['optionTexts'] as string[] | undefined) ?? [];
    setOptionTexts(saved.length > 0 ? saved : ['']);
    setMode('edit');
  };

  const openAnswer = () => {
    setAnswerQuestionId('');
    setAnswerOptionId('');
    setAnswerText('');
    setOtherOpinion('');
    setMode('answer');
  };

  const setOptionText = (index: number, text: string) => {
    setOptionTexts(optionTexts.map((t, i) => (i === index ? text : t)));
  };

  const buildBody = (): Row => {
    if (title.trim() === '') {
      throw new Error('설문항목 제목을 입력해 주세요.');
    }
    const body: Row = {
      title: title.trim(),
      questionType,
      otherOpinionAllowed: otherAllowed === 'true',
    };
    if (sortOrder !== '') {
      body.sortOrder = sortOrder;
    }
    if (questionType === '선택형') {
      const texts = optionTexts.map((t) => t.trim()).filter((t) => t !== '');
      if (texts.length === 0) {
        throw new Error('선택형 문항은 보기를 하나 이상 입력해 주세요.');
      }
      body.selectionMode = selectionMode;
      body.options = texts.map((t, i) => ({ optionText: t, sortOrder: i }));
    }
    return body;
  };

  const toRow = (res: Row, body: Row, sid: number | string): Row => ({
    surveyQuestionId: res['surveyQuestionId'],
    surveyId: sid,
    title: res['title'],
    questionType: res['questionType'],
    selectionMode: res['selectionMode'],
    otherOpinionAllowed: res['otherOpinionAllowed'],
    sortOrder: body['sortOrder'] ?? '',
    optionTexts: ((body['options'] as Row[] | undefined) ?? []).map((o) => String(o['optionText'])),
  });

  const submitQuestion = async () => {
    if (mode === 'create' && surveyId === '') {
      throw new Error('설문조사를 선택해 주세요.');
    }
    const body = buildBody();
    if (mode === 'create') {
      const res = await call('POST', '/survey-questions', role, { ...body, surveyId });
      setQuestions([...questions, toRow(res, body, surveyId)]);
      notify('설문항목을 등록했습니다.');
    } else if (editing) {
      const id = editing['surveyQuestionId'];
      const res = await call('PUT', `/survey-questions/${id}`, role, body);
      setQuestions(questions.map((q) => (q['surveyQuestionId'] === id ? toRow(res, body, surveyId) : q)));
      notify('설문항목을 수정했습니다.');
    }
    close();
  };

  const picked = questions.find((q) => q['surveyQuestionId'] === answerQuestionId);
  const showOption = !picked || picked['questionType'] === '선택형';
  const showText = !picked || picked['questionType'] === '주관식';
  const showOther = !picked || picked['otherOpinionAllowed'] === true;

  const submitAnswer = async () => {
    if (answerQuestionId === '') {
      throw new Error('설문항목을 선택해 주세요.');
    }
    if (picked && picked['questionType'] === '선택형' && answerOptionId === '') {
      throw new Error('보기를 선택해 주세요.');
    }
    if (picked && picked['questionType'] === '주관식' && answerText.trim() === '') {
      throw new Error('응답 내용을 입력해 주세요.');
    }
    const body: Row = { surveyQuestionId: answerQuestionId };
    if (showOption && answerOptionId !== '') {
      body.surveyOptionId = answerOptionId;
    }
    if (showText && answerText.trim() !== '') {
      body.answerText = answerText;
    }
    if (showOther && otherOpinion.trim() !== '') {
      body.otherOpinion = otherOpinion;
    }
    const res = await call('POST', '/survey-answers', role, body);
    setAnswers([{ surveyAnswerId: res['surveyAnswerId'], surveyQuestionId: answerQuestionId, surveyOptionId: body['surveyOptionId'] ?? '', answerText: body['answerText'] ?? '' }, ...answers]);
    notify('응답을 제출했습니다.');
    close();
  };

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>처리 현황</h2>
        <Tiles items={[['등록한 설문항목', questions.length], ['제출한 응답', answers.length]]} />
      </section>
      <section className="box span-8">
        <h2>설문항목</h2>
        <Band total={questions.length}>
          <button type="button" onClick={openCreate}>설문항목 등록</button>
          <button type="button" onClick={openAnswer}>응답 입력</button>
        </Band>
        <DataTable
          rows={questions}
          onRowClick={openEdit}
          empty="이 화면에서 등록한 설문항목이 없습니다."
          columns={[
            { key: 'surveyQuestionId', label: '설문항목 ID' },
            { key: 'surveyId', label: '설문조사', render: (r) => <RefName table="survey" role={role} value={r['surveyId']} /> },
            { key: 'title', label: '설문항목 제목' },
            { key: 'questionType', label: '문항 유형', render: (r) => <Badge value={r['questionType']} /> },
            { key: 'selectionMode', label: '선택 방식', render: (r) => <span>{String(r['selectionMode'] ?? '-')}</span> },
            { key: 'otherOpinionAllowed', label: '기타의견 허용', render: (r) => <span>{r['otherOpinionAllowed'] === true ? '허용' : '불허'}</span> },
          ]}
        />
      </section>
      <section className="box span-4">
        <h2>최근 응답</h2>
        <DataTable
          rows={answers}
          empty="제출한 응답이 없습니다."
          columns={[
            { key: 'surveyQuestionId', label: '설문항목', render: (r) => <RefName table="survey_question" role={role} value={r['surveyQuestionId']} /> },
            { key: 'surveyOptionId', label: '선택 보기', render: (r) => (r['surveyOptionId'] === '' ? <span>-</span> : <RefName table="survey_option" role={role} value={r['surveyOptionId']} />) },
            { key: 'answerText', label: '주관식 응답 내용' },
          ]}
        />
      </section>
      {(mode === 'create' || mode === 'edit') && (
        <Drawer title={mode === 'create' ? '설문항목 등록' : '설문항목 수정'} onClose={close}>
          <Form onSubmit={submitQuestion} submit={mode === 'create' ? '등록' : '수정'}>
            {mode === 'create' && (
              <Field label="설문조사" required>
                <LookupSelect table="survey" role={role} value={surveyId} onChange={setSurveyId} />
              </Field>
            )}
            <Field label="설문항목 제목" required wide>
              <TextInput value={title} onChange={setTitle} />
            </Field>
            <Field label="문항 유형" required>
              <Select value={questionType} onChange={setQuestionType} options={[['선택형', '선택형'], ['주관식', '주관식']]} />
            </Field>
            {questionType === '선택형' && (
              <Field label="선택 방식" required>
                <Select value={selectionMode} onChange={setSelectionMode} options={[['단답', '단답'], ['다답', '다답']]} />
              </Field>
            )}
            <Field label="기타의견 허용" required>
              <Select value={otherAllowed} onChange={setOtherAllowed} options={[['true', '허용'], ['false', '불허']]} />
            </Field>
            <Field label="표시 순서">
              <NumberInput value={sortOrder} onChange={setSortOrder} />
            </Field>
            {questionType === '선택형' && (
              <Field label="보기 목록" required wide hint="보기는 입력한 순서대로 표시됩니다.">
                <div>
                  {optionTexts.map((text, index) => (
                    <div key={index}>
                      <TextInput value={text} onChange={(v) => setOptionText(index, v)} placeholder={`보기 ${index + 1}`} />
                    </div>
                  ))}
                  <button type="button" onClick={() => setOptionTexts([...optionTexts, ''])}>보기 추가</button>
                </div>
              </Field>
            )}
          </Form>
        </Drawer>
      )}
      {mode === 'answer' && (
        <Drawer title="설문 응답 입력" onClose={close}>
          <Form onSubmit={submitAnswer} submit="제출">
            <Field label="설문항목" required>
              <LookupSelect table="survey_question" role={role} value={answerQuestionId} onChange={setAnswerQuestionId} />
            </Field>
            {showOption && (
              <Field label="선택 보기" hint="선택형 문항에서 보기를 고릅니다. 다답형은 보기마다 제출합니다.">
                <LookupSelect table="survey_option" role={role} value={answerOptionId} onChange={setAnswerOptionId} />
              </Field>
            )}
            {showText && (
              <Field label="주관식 응답 내용" wide>
                <TextInput value={answerText} onChange={setAnswerText} multiline />
              </Field>
            )}
            {showOther && (
              <Field label="기타 의견" wide hint="기타의견이 허용된 문항에서만 입력할 수 있습니다.">
                <TextInput value={otherOpinion} onChange={setOtherOpinion} multiline />
              </Field>
            )}
          </Form>
        </Drawer>
      )}
    </div>
  );
}
